export function getPinyin(char: string): string {
  const raw = PINYIN_MAP[char] || ''
  return raw ? convertToneNumber(raw) : ''
}

const TONE_MARKS: Record<string, string[]> = {
  'a': ['\u0101', '\u00e1', '\u01ce', '\u00e0', 'a'],
  'e': ['\u0113', '\u00e9', '\u011b', '\u00e8', 'e'],
  'i': ['\u012b', '\u00ed', '\u01d0', '\u00ec', 'i'],
  'o': ['\u014d', '\u00f3', '\u01d2', '\u00f2', 'o'],
  'u': ['\u016b', '\u00fa', '\u01d4', '\u00f9', 'u'],
  'v': ['\u01d6', '\u01d8', '\u01da', '\u01dc', '\u00fc'],
  '\u00fc': ['\u01d6', '\u01d8', '\u01da', '\u01dc', '\u00fc'],
}

function convertToneNumber(pinyin: string): string {
  const match = pinyin.match(/^([a-z\u00fc]+)([1-5])$/)
  if (!match) return pinyin.replace(/v/g, '\u00fc')

  let syllables = match[1].replace(/v/g, '\u00fc')
  const tone = parseInt(match[2])

  if (tone === 5) return syllables

  const toneIdx = tone - 1

  // Rule: mark goes on 'a' or 'e' if present
  for (const vowel of ['a', 'e']) {
    if (syllables.includes(vowel)) {
      return syllables.replace(vowel, TONE_MARKS[vowel][toneIdx])
    }
  }

  // Rule: in 'ou', mark goes on 'o'
  if (syllables.includes('ou')) {
    return syllables.replace('o', TONE_MARKS['o'][toneIdx])
  }

  // Otherwise, mark goes on the last vowel
  const vowels = syllables.match(/[aeiou\u00fc]/g)
  if (vowels && vowels.length > 0) {
    const lastVowel = vowels[vowels.length - 1]
    return syllables.replace(
      new RegExp(`${lastVowel}(?!.*[aeiou\u00fc])`),
      TONE_MARKS[lastVowel][toneIdx]
    )
  }

  return syllables
}

export function addPinyinToText(text: string): { char: string; pinyin: string }[] {
  return Array.from(text).map(ch => ({
    char: ch,
    pinyin: (ch >= '\u4e00' && ch <= '\u9fff') ? getPinyin(ch) : '',
  }))
}
